	@Test
	void maybeBoundUnknownInputDoesNotCreateAFixedOrNarrowKindProof() {
		StatementPattern valued = statementPattern(Var.of("x", S, false, false));
		QueryAlgebraBindingAnalysis empty = QueryAlgebraBindingAnalysis.withBindingValues(valued,
				EmptyBindingSet.getInstance());
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withInputContextAndPossibleInputs(valued,
				empty.rootContext(), Set.of("x"));
		QueryAlgebraBindingAnalysis.ReadOnlyContext input = analysis.contextAt(valued);
		OutputFacts facts = analysis.outputFacts(valued, input);

		assertThat(input.maybeBoundNames()).contains("x");
		assertThat(input.guaranteedNames()).doesNotContain("x");
		assertThat(facts.canProduceRows()).isTrue();
		assertThat(facts.fixedValues()).doesNotContainKey("x");
		Set<ValueKind> kinds = facts.valueKinds().get("x");
		if (kinds != null && !kinds.contains(ValueKind.UNKNOWN)) {
			assertThat(kinds).contains(ValueKind.IRI, ValueKind.BNODE, ValueKind.LITERAL, ValueKind.TRIPLE);
		}
	}

