		TripleRef candidate = new TripleRef(Var.of("subject", S, false, false), constant(P), constant(O),
				Var.of("term"));
		Source source = new Source(statementData(), List.of(term));
		BindingSet request = BindingSetOrigin.optimizationInput(bindings("subject", S));
		BindingSet untrusted = BindingSetOrigin.produced(EmptyBindingSet.getInstance(), Set.of("subject"));

		List<Map<String, Value>> requestRows = rows(source, candidate, request);
