	@Test
	void completeStandardPipelinePreservesTheCorrelatedSameTermBag() {
		Model data = sameTermData();
		Source source = new Source(data);
		TupleExpr original = parse("SELECT ?s WHERE { ?s :p ?x FILTER EXISTS { ?s :q ?x FILTER(sameTerm(?x, :v1)) } }");
		List<Map<String, Value>> expected = List.of(Map.of("s", VF.createIRI("urn:t:s2")));
		assertThat(rows(source, original, EmptyBindingSet.getInstance())).containsExactlyElementsOf(expected);

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, url -> null);
		TupleExpr optimized = original.clone();
		strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		assertThat(rows(source, optimized, EmptyBindingSet.getInstance()))
				.as("full standard optimizer pipeline\n%s", optimized)
				.containsExactlyElementsOf(expected);
	}

	@Test
	void completeStandardPipelineStillInlinesTheUncorrelatedSameTerm() {
		Model data = sameTermData();
		Source source = new Source(data);
		TupleExpr original = parse("SELECT ?s WHERE { ?s :q ?x FILTER(sameTerm(?x, :v1)) }");
		List<Map<String, Value>> expected = List.of(
				Map.of("s", VF.createIRI("urn:t:s1")),
				Map.of("s", VF.createIRI("urn:t:s2")));
		assertThat(rows(source, original, EmptyBindingSet.getInstance()))
				.containsExactlyInAnyOrderElementsOf(expected);

		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, url -> null);
		TupleExpr optimized = original.clone();
		strategy.optimize(optimized, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		assertThat(rows(source, optimized, EmptyBindingSet.getInstance()))
				.containsExactlyInAnyOrderElementsOf(expected);
		List<StatementPattern> patterns = new ArrayList<>();
		optimized.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern pattern) {
				if (VF.createIRI("urn:t:q").equals(pattern.getPredicateVar().getValue())) {
					patterns.add(pattern);
				}
				super.meet(pattern);
			}
		});
		assertThat(patterns).singleElement().satisfies(pattern -> {
			assertThat(pattern.getObjectVar().hasValue()).isTrue();
			assertThat(pattern.getObjectVar().getValue()).isEqualTo(VF.createIRI("urn:t:v1"));
		});
	}


	@Test
	void defaultGraphContextIsNotAGuaranteedRdfValueAcrossBindingLayouts() {
		IRI namedGraph = VF.createIRI("urn:fixed:graph");
		Model data = new LinkedHashModel();
		data.add(S, P, O);
		data.add(S, P, O, namedGraph);
		Source source = new Source(data);
		StatementPattern unvalued = new StatementPattern(Scope.DEFAULT_CONTEXTS, constant(S), constant(P), constant(O),
				Var.of("g"));
		for (QueryEvaluationContext context : List.of(queryBindingContext(), arrayBindingContext("g"))) {
			List<BindingSet> actual = statementRows(source, unvalued, context);
			assertThat(actual).hasSize(2);
			BindingSet defaultRow = actual.stream().filter(row -> row.getValue("g") == null).findFirst().orElseThrow();
			assertThat(defaultRow.getBinding("g")).isNull();
			assertThat(defaultRow.getValue("g")).isNull();
			if (defaultRow instanceof org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet) {
				assertThat(defaultRow.hasBinding("g"))
						.as("QueryBindingSet exposes its null slot through hasBinding, but has no RDF Binding value")
						.isTrue();
			} else {
				assertThat(defaultRow.hasBinding("g")).isFalse();
			}
			assertThat(actual).anySatisfy(row -> assertThat(row.getValue("g")).isEqualTo(namedGraph));
		}
		QueryAlgebraBindingAnalysis unvaluedAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(unvalued,
				EmptyBindingSet.getInstance());
		OutputFacts unvaluedFacts = unvaluedAnalysis.outputFacts(unvalued, unvaluedAnalysis.contextAt(unvalued));
		assertThat(unvaluedFacts.guaranteedOutputs()).doesNotContain("g");
		assertThat(unvaluedFacts.fixedValues()).doesNotContainKey("g");
		Set<ValueKind> mixedContextKinds = unvaluedFacts.valueKinds().get("g");
		assertThat(mixedContextKinds == null || mixedContextKinds.contains(ValueKind.UNKNOWN)
				|| mixedContextKinds.equals(Set.of(ValueKind.IRI)))
				.as("only the non-null named-graph rows can establish an IRI kind: %s", mixedContextKinds).isTrue();

		BindingSet namedInput = bindings("g", namedGraph);
		assertThat(rows(source, unvalued, namedInput)).containsExactly(Map.of("g", namedGraph));
		QueryAlgebraBindingAnalysis namedAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(unvalued,
				namedInput);
		OutputFacts namedFacts = namedAnalysis.outputFacts(unvalued, namedAnalysis.contextAt(unvalued));
		assertObservedValueIsNotExcluded(namedFacts, "g", namedGraph);

		for (Value nullGraphSentinel : List.of(RDF4J.NIL, SESAME.NIL)) {
			StatementPattern defaultAlias = new StatementPattern(Scope.DEFAULT_CONTEXTS, constant(S), constant(P),
					constant(O), Var.of("g", nullGraphSentinel, false, false));
			for (QueryEvaluationContext context : List.of(queryBindingContext(), arrayBindingContext("g"))) {
				List<BindingSet> actual = statementRows(source, defaultAlias, context);
				assertThat(actual).hasSize(1);
				assertThat(actual.getFirst().getBinding("g")).isNull();
				assertThat(actual.getFirst().getValue("g")).isNull();
			}
			QueryAlgebraBindingAnalysis aliasAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(defaultAlias,
					EmptyBindingSet.getInstance());
			OutputFacts aliasFacts = aliasAnalysis.outputFacts(defaultAlias, aliasAnalysis.contextAt(defaultAlias));
			assertThat(aliasFacts.guaranteedOutputs()).doesNotContain("g");
			assertThat(aliasFacts.fixedValues()).doesNotContainKey("g");
			Set<ValueKind> aliasKinds = aliasFacts.valueKinds().get("g");
			assertThat(aliasKinds == null || aliasKinds.isEmpty() || aliasKinds.contains(ValueKind.UNKNOWN))
					.as("%s selects a null default graph and is not emitted as an IRI: %s", nullGraphSentinel, aliasKinds)
					.isTrue();
		}
	}

	@Test
	void namedScopeDoesNotProveGraphBindingWhenDatasetContainsDefaultAlias() {
		IRI namedGraph = VF.createIRI("urn:fixed:dataset-named-graph");
		Model data = new LinkedHashModel();
		data.add(S, P, O);
		data.add(S, P, O, namedGraph);
		Source source = new Source(data);
		StatementPattern namedPattern = new StatementPattern(Scope.NAMED_CONTEXTS, constant(S), constant(P),
				constant(O), Var.of("g"));
		List<BindingSet> nilRows = new ArrayList<>();
		for (Value nullGraphAlias : List.of(RDF4J.NIL, SESAME.NIL)) {
			SimpleDataset dataset = new SimpleDataset();
			dataset.addNamedGraph((Resource) nullGraphAlias);
			dataset.addNamedGraph(namedGraph);
			nilRows.addAll(statementRows(source, namedPattern,
					new QueryEvaluationContext.Minimal(dataset)));
		}
		SimpleDataset namedOnlyDataset = new SimpleDataset();
		namedOnlyDataset.addNamedGraph(namedGraph);
		List<BindingSet> namedOnlyRows = statementRows(source, namedPattern,
				new QueryEvaluationContext.Minimal(namedOnlyDataset));

		// The real SimpleDataset maps each NIL alias to the default data graph. With another selected graph it passes
		// that null context through the NAMED physical scan, so NAMED scope alone cannot prove an RDF-valued binding.
		assertThat(nilRows).hasSize(4);
		assertThat(nilRows).filteredOn(row -> row.getValue("g") == null).hasSize(2);
		assertThat(nilRows).filteredOn(row -> namedGraph.equals(row.getValue("g"))).hasSize(2);
		assertThat(namedOnlyRows).hasSize(1);
		assertThat(namedOnlyRows.getFirst().getValue("g")).isEqualTo(namedGraph);

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(namedPattern,
				EmptyBindingSet.getInstance());
		OutputFacts facts = analysis.outputFacts(namedPattern, analysis.contextAt(namedPattern));
		assertThat(facts.guaranteedOutputs()).doesNotContain("g");
		assertThat(facts.fixedValues()).doesNotContainKey("g");
	}

	@Test
	void valuedLookupRepresentativeIsNotAnExactLangInput() {
		Literal stored = VF.createLiteral("label", "EN");
		Literal lookup = VF.createLiteral("label", "en");
		assertThat(stored).isEqualTo(lookup);
		assertThat(stored.getLanguage()).contains("EN");
		assertThat(lookup.getLanguage()).contains("en");
		Model data = new LinkedHashModel();
		data.add(S, P, stored);
		Source source = new Source(data);
		try (CloseableIteration<? extends Statement> readback = source.getStatements(S, P, lookup)) {
			assertThat(readback.hasNext()).isTrue();
			assertThat(readback.next().getObject()).isSameAs(stored);
			assertThat(readback.hasNext()).isFalse();
		}

		Filter valuedFilter = languageFilter(lookup, "EN");
		List<BindingSet> ordinaryBindings = bindingSets(source, valuedFilter, EmptyBindingSet.getInstance());
		assertThat(ordinaryBindings).singleElement().satisfies(row -> assertThat(row.getValue("x")).isSameAs(stored));
		List<Map<String, Value>> ordinary = rows(ordinaryBindings);
		assertThat(ordinary).containsExactly(Map.of("s", S, "x", stored));

		Filter sameRepresentativeFilter = languageFilter(stored, "EN");
		List<Map<String, Value>> safeOrdinary = rows(source, sameRepresentativeFilter,
				EmptyBindingSet.getInstance());
		assertThat(safeOrdinary).containsExactly(Map.of("s", S, "x", stored));
		TupleExpr safeOptimized = new QueryRoot(sameRepresentativeFilter.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(safeOptimized, new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		assertThat(rows(source, safeOptimized, EmptyBindingSet.getInstance())).containsExactlyElementsOf(safeOrdinary);

		BindingSet alreadyBound = bindings("x", stored);
		List<Map<String, Value>> boundOrdinary = rows(source, valuedFilter, alreadyBound);
		assertThat(boundOrdinary).containsExactly(Map.of("s", S, "x", stored));
		TupleExpr boundOptimized = new QueryRoot(valuedFilter.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(boundOptimized, new EvaluationStatistics(),
				alreadyBound);
		assertThat(rows(source, boundOptimized, alreadyBound)).containsExactlyElementsOf(boundOrdinary);

		TupleExpr optimized = new QueryRoot(valuedFilter.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(optimized, new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		assertThat(rows(source, optimized, EmptyBindingSet.getInstance())).containsExactlyElementsOf(ordinary);
	}

