	@Test
	void tupleObservationDomainsIncludeModifiersAndScopeMetadataOrDeclineUnknownNodes() {
		Filter filter = new Filter(new SingletonSet(), new Bound(Var.of("filterName")));
		TupleExprs.ConditionBindingDomain condition = TupleExprs.conditionBindingDomain(filter.getCondition());
		assertThat(condition.known()).isTrue();
		assertThat(condition.names()).containsExactly("filterName");

		Exists exists = new Exists(new Filter(new SingletonSet(), new Bound(Var.of("existsName"))));
		TupleExprs.ConditionBindingDomain existsDomain = TupleExprs.tupleBindingObservationDomain(
				new Filter(new SingletonSet(), exists));
		assertThat(existsDomain.known()).isTrue();
		assertThat(existsDomain.names()).contains("existsName");

		Difference minus = new Difference(new SingletonSet(),
				new Filter(new SingletonSet(), new Bound(Var.of("minusName"))));
		TupleExprs.ConditionBindingDomain minusDomain = TupleExprs.tupleBindingObservationDomain(minus);
		assertThat(minusDomain.known()).isTrue();
		assertThat(minusDomain.names()).contains("minusName");

		Order order = new Order(new SingletonSet(), new OrderElem(Var.of("orderName")));
		TupleExprs.ConditionBindingDomain orderDomain = TupleExprs.tupleBindingObservationDomain(order);
		assertThat(orderDomain.known()).isTrue();
		assertThat(orderDomain.names()).contains("orderName");

		Projection projection = new Projection(values("sourceName", CALLER_LITERAL),
				new ProjectionElemList(new ProjectionElem("sourceName", "projectedName")));
		TupleExprs.ConditionBindingDomain projectionDomain = TupleExprs.tupleBindingObservationDomain(projection);
		assertThat(projectionDomain.known()).isTrue();
		assertThat(projectionDomain.names()).contains("sourceName", "projectedName");

		Lateral lateral = new Lateral(new SingletonSet(), new SingletonSet(), Set.of("lateralInput"));
		TupleExprs.ConditionBindingDomain lateralDomain = TupleExprs.tupleBindingObservationDomain(lateral);
		assertThat(lateralDomain.known()).isTrue();
		assertThat(lateralDomain.names()).contains("lateralInput");

		TupleExprs.ConditionBindingDomain unknown = TupleExprs.tupleBindingObservationDomain(
				new Distinct(new SingletonSet()));
		assertThat(unknown.known()).as("whole-row DISTINCT remains an unknown observation domain").isFalse();
	}

