	@Test
	void joinFactsRequireRepresentativeAgreementAcrossBothInputs() {
		Literal upper = VF.createLiteral("label", "EN");
		Literal lower = VF.createLiteral("label", "en");
		Source source = new Source(new LinkedHashModel());
		List<Join> joins = List.of(new Join(values(upper, lower), values(upper)),
				new Join(values(upper), values(upper, lower)));
		List<OutputFacts> facts = new ArrayList<>();
		List<List<BindingSet>> rows = new ArrayList<>();
		for (Join join : joins) {
			List<BindingSet> ordinary = bindingSets(source, join, EmptyBindingSet.getInstance());
			assertThat(ordinary).hasSize(2);
			rows.add(ordinary);
			QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(join,
					EmptyBindingSet.getInstance());
			facts.add(analysis.outputFacts(join, analysis.contextAt(join)));
		}
		assertThat(rows.get(0).get(0).getValue("x")).isSameAs(upper);
		assertThat(rows.get(0).get(1).getValue("x")).isSameAs(lower);
		assertThat(rows.get(1)).allSatisfy(row -> assertThat(row.getValue("x")).isSameAs(upper));
		assertThat(facts.get(0).fixedValues()).doesNotContainKey("x");
		assertThat(facts.get(1).fixedValues().get("x")).isSameAs(upper);
	}

