	@Test
	void failedLateralExtensionKeepsItsLeftInputBinding() {
		Lateral candidate = failedExtensionLateral();
		Source source = new Source(new LinkedHashModel());
		List<Map<String, Value>> expected = List.of(Map.of("x", CALLER_LITERAL));
		assertThat(rows(source, candidate, EmptyBindingSet.getInstance())).containsExactlyElementsOf(expected);

		Filter bound = new Filter(candidate.clone(), new Bound(Var.of("x")));
		assertThat(rows(source, bound, EmptyBindingSet.getInstance())).containsExactlyElementsOf(expected);
		TupleExpr optimized = new QueryRoot(bound.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(optimized, new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		assertThat(rows(source, optimized, EmptyBindingSet.getInstance()))
				.as("Lateral merges a failed RHS row with the left mapping\n%s", optimized)
				.containsExactlyElementsOf(expected);

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(candidate,
				EmptyBindingSet.getInstance());
		OutputFacts facts = analysis.outputFacts(candidate, analysis.contextAt(candidate));
		assertThat(facts.guaranteedOutputs())
				.as("Lateral retains the left binding when the RHS has no successful write")
				.contains("x");
		assertThat(facts.fixedValues().get("x")).isSameAs(CALLER_LITERAL);
		assertThat(facts.valueKinds().get("x")).contains(ValueKind.LITERAL);
	}

