	@Test
	void aSuccessfulDependentRhsWriteStillGuaranteesItsOutput() {
		Source source = new Source(new LinkedHashModel());
		for (TupleExpr candidate : List.of(successfulExtensionJoin(), successfulExtensionLeftJoin())) {
			List<Map<String, Value>> ordinary = rows(source, candidate, EmptyBindingSet.getInstance());
			assertThat(ordinary).as("successful RHS write: %s", candidate).containsExactly(Map.of("x", T));

			QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(candidate,
					EmptyBindingSet.getInstance());
			OutputFacts facts = analysis.outputFacts(candidate, analysis.contextAt(candidate));
			assertThat(facts.guaranteedOutputs())
				.as("successful RHS write remains guaranteed: %s", candidate).contains("x");
			if (candidate instanceof Join) {
				assertThat(facts.fixedValues().get("x")).isSameAs(T);
				assertThat(facts.valueKinds().get("x")).containsExactly(ValueKind.IRI);
			} else {
				assertThat(facts.fixedValues()).doesNotContainKey("x");
				assertThat(facts.valueKinds().get("x")).contains(ValueKind.LITERAL, ValueKind.IRI);
			}
		}

		Lateral lateral = successfulExtensionLateral();
		List<Map<String, Value>> lateralRows = rows(source, lateral, EmptyBindingSet.getInstance());
		assertThat(lateralRows).containsExactly(Map.of("x", CALLER_LITERAL, "y", CALLER_LITERAL));
		QueryAlgebraBindingAnalysis lateralAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(lateral,
				EmptyBindingSet.getInstance());
		OutputFacts lateralFacts = lateralAnalysis.outputFacts(lateral, lateralAnalysis.contextAt(lateral));
		assertThat(lateralFacts.guaranteedOutputs())
				.contains("x", "y");
		assertThat(lateralFacts.fixedValues().get("x")).isSameAs(CALLER_LITERAL);
		assertThat(lateralFacts.valueKinds().get("x")).contains(ValueKind.LITERAL);
	}

