	@Test
	void unvaluedStatementInputPreparerCanChangeLangRepresentative() {
		Literal caller = VF.createLiteral("label", "EN");
		Literal storedValue = VF.createLiteral("label", "EN");
		Literal prepared = VF.createLiteral("label", "en");
		assertThat(caller).isEqualTo(prepared);
		assertThat(storedValue).isEqualTo(prepared);
		assertThat(storedValue).isNotSameAs(caller);
		Statement stored = VF.createStatement(S, P, storedValue);
		List<Value> preparedInputs = new ArrayList<>();
		List<Value> preparedOutputs = new ArrayList<>();
		List<Value> queryLookupObjects = new ArrayList<>();
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
				queryLookupObjects.add(object);
				assertThat(object).isEqualTo(prepared);
				return new CloseableIteratorIteration<>(List.of(stored).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}

			@Override
			public java.util.function.Function<Value, Value> getValuePreparer() {
				return value -> {
					preparedInputs.add(value);
					Value result = caller.equals(value) ? prepared : value;
					preparedOutputs.add(result);
					return result;
				};
			}
		};
		Filter filter = new Filter(new StatementPattern(Var.of("s"), constant(P), Var.of("x")),
				new Compare(new Lang(Var.of("x")), new ValueConstant(VF.createLiteral("EN"))));
		BindingSet input = bindings("x", caller);
		List<BindingSet> ordinaryBindings = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = new StrictEvaluationStrategy(source, null)
				.precompile(filter).evaluate(input)) {
			while (iteration.hasNext()) {
				ordinaryBindings.add(iteration.next());
			}
		}
		List<Value> returnedValues = ordinaryBindings.stream().map(row -> row.getValue("x")).toList();
		List<Value> directReadbackValues = new ArrayList<>();
		try (CloseableIteration<? extends Statement> readback = source.getStatements(S, P, prepared)) {
			while (readback.hasNext()) {
				directReadbackValues.add(readback.next().getObject());
			}
		}
		String trace = "preparerSawCaller=" + preparedInputs.stream().anyMatch(value -> value == caller)
				+ ", preparerReturnedDistinctValue=" + preparedOutputs.stream().anyMatch(value -> value == prepared)
				+ ", queryLookedUpPreparedValue=" + queryLookupObjects.stream().anyMatch(value -> value == prepared)
				+ ", directReadbackIsStoredValue=" + directReadbackValues.stream().anyMatch(value -> value == storedValue)
				+ ", returnedSameCaller=" + returnedValues.stream().anyMatch(value -> value == caller)
				+ ", returnedSameStored=" + returnedValues.stream().anyMatch(value -> value == storedValue)
				+ ", returnedSamePrepared=" + returnedValues.stream().anyMatch(value -> value == prepared)
				+ ", returnLanguages=" + returnedValues.stream().map(value -> ((Literal) value).getLanguage()).toList()
				+ ", returnedValues=" + returnedValues;
		assertThat(preparedInputs).as(trace).anySatisfy(value -> assertThat(value).isSameAs(caller));
		assertThat(preparedOutputs).as(trace).anySatisfy(value -> assertThat(value).isSameAs(prepared));
		assertThat(queryLookupObjects).as(trace).anySatisfy(value -> assertThat(value).isSameAs(prepared));
		assertThat(directReadbackValues).as(trace).containsExactly(storedValue);
		List<Map<String, Value>> ordinary = new ArrayList<>();
		for (BindingSet row : ordinaryBindings) {
			Map<String, Value> map = new TreeMap<>();
			for (String name : row.getBindingNames()) {
				map.put(name, row.getValue(name));
			}
			ordinary.add(Map.copyOf(map));
		}
		assertThat(ordinary).as(trace).isEmpty();
		TupleExpr optimized = new QueryRoot(filter.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(optimized, new EvaluationStatistics(), input);
		List<BindingSet> optimizedBindings = new ArrayList<>();
		// SailSourceConnection evaluates an optimized plan with request mappings in origin metadata. This models that
		// query-entry route; the unoptimized raw mapping above intentionally exercises the separate low-level contract.
		try (CloseableIteration<BindingSet> iteration = new StrictEvaluationStrategy(source, null)
				.precompile(optimized).evaluate(BindingSetOrigin.optimizationInput(input))) {
			while (iteration.hasNext()) {
				optimizedBindings.add(iteration.next());
			}
		}
		List<Value> optimizedValues = optimizedBindings.stream().map(row -> row.getValue("x")).toList();
		List<Map<String, Value>> optimizedRows = new ArrayList<>();
		for (BindingSet row : optimizedBindings) {
			optimizedRows.add(Map.of("s", row.getValue("s"), "x", row.getValue("x")));
		}
		String optimizedTrace = trace + ", optimizedValues=" + optimizedValues
				+ ", optimizedSameCaller=" + optimizedValues.stream().anyMatch(value -> value == caller)
				+ ", optimizedSameStored=" + optimizedValues.stream().anyMatch(value -> value == storedValue)
				+ ", optimizedSamePrepared=" + optimizedValues.stream().anyMatch(value -> value == prepared)
				+ ", optimizedTree=" + optimized;
		assertThat(optimizedRows).as(optimizedTrace).singleElement().satisfies(row -> {
			assertThat(row.get("s")).isEqualTo(S);
			assertThat(row.get("x")).isSameAs(caller);
		});
	}

	private static Filter languageFilter(Literal lookup, String language) {
		StatementPattern pattern = new StatementPattern(Var.of("s"), constant(P),
				Var.of("x", lookup, false, false));
		return new Filter(pattern,
				new Compare(new Lang(Var.of("x")), new ValueConstant(VF.createLiteral(language))));
	}

	@Test
	void unvaluedConstantTripleRefSubjectAndExpressionReadAndRetainAbsentOrPreboundValues() {
		TripleTerm term = VF.createTripleTerm(S, P, O);
		BNode reifier = VF.createBNode("encoded-proposition");
		Literal encodedSubject = VF.createLiteral("encoded subject value");
		Literal encodedPredicate = VF.createLiteral("encoded predicate value");
		List<TripleRefCase> cases = List.of(
				new TripleRefCase(new Source(statementData(), List.of(term)), S, P, O, term),
				new TripleRefCase(encodedSource(reifier, encodedSubject, encodedPredicate, O), encodedSubject,
						encodedPredicate, O, reifier));

		for (TripleRefCase testCase : cases) {
			TripleRef constantSubjectWithoutValue = new TripleRef(Var.of("s", null, false, true), Var.of("p"),
					Var.of("o"), Var.of("expr"));
			Map<String, Value> expected = Map.of("s", testCase.subject(), "p", testCase.predicate(), "o",
					testCase.object(), "expr", testCase.expression());
			assertThat(rows(testCase.source(), constantSubjectWithoutValue, EmptyBindingSet.getInstance()))
					.containsExactly(expected);
			QueryAlgebraBindingAnalysis absentSubject = QueryAlgebraBindingAnalysis.withBindingValues(
					constantSubjectWithoutValue, EmptyBindingSet.getInstance());
			OutputFacts subjectFacts = absentSubject.outputFacts(constantSubjectWithoutValue,
					absentSubject.contextAt(constantSubjectWithoutValue));
			assertPossibleOutputIfKnown(subjectFacts, "s");
			assertObservedValueIsNotExcluded(subjectFacts, "s", testCase.subject());

			BindingSet subjectInput = bindings("s", testCase.subject());
			assertThat(rows(testCase.source(), constantSubjectWithoutValue, subjectInput)).containsExactly(expected);
			QueryAlgebraBindingAnalysis suppliedSubject = QueryAlgebraBindingAnalysis.withBindingValues(
					constantSubjectWithoutValue, subjectInput);
			OutputFacts suppliedSubjectFacts = suppliedSubject.outputFacts(constantSubjectWithoutValue,
						suppliedSubject.contextAt(constantSubjectWithoutValue));
			assertObservedValueIsNotExcluded(suppliedSubjectFacts, "s", testCase.subject());
			assertThat(suppliedSubject.contextAt(constantSubjectWithoutValue).fixedValues().get("s"))
					.isEqualTo(testCase.subject());

			TripleRef constantExpressionWithoutValue = new TripleRef(Var.of("s"), Var.of("p"), Var.of("o"),
					Var.of("expr", null, false, true));
			assertThat(rows(testCase.source(), constantExpressionWithoutValue, EmptyBindingSet.getInstance()))
					.containsExactly(expected);
			QueryAlgebraBindingAnalysis absentExpression = QueryAlgebraBindingAnalysis.withBindingValues(
					constantExpressionWithoutValue, EmptyBindingSet.getInstance());
			OutputFacts expressionFacts = absentExpression.outputFacts(constantExpressionWithoutValue,
					absentExpression.contextAt(constantExpressionWithoutValue));
			assertPossibleOutputIfKnown(expressionFacts, "expr");
			assertObservedValueIsNotExcluded(expressionFacts, "expr", testCase.expression());

			BindingSet expressionInput = bindings("expr", testCase.expression());
			assertThat(rows(testCase.source(), constantExpressionWithoutValue, expressionInput)).containsExactly(expected);
			QueryAlgebraBindingAnalysis suppliedExpression = QueryAlgebraBindingAnalysis.withBindingValues(
					constantExpressionWithoutValue, expressionInput);
			OutputFacts suppliedExpressionFacts = suppliedExpression.outputFacts(constantExpressionWithoutValue,
						suppliedExpression.contextAt(constantExpressionWithoutValue));
			assertObservedValueIsNotExcluded(suppliedExpressionFacts, "expr", testCase.expression());
			assertThat(suppliedExpression.contextAt(constantExpressionWithoutValue).fixedValues().get("expr"))
					.isEqualTo(testCase.expression());
		}
	}

