	@Test
	void valuedPathContextRetainsCallerOnFirstHopAndUsesLookupGraphForExpansion() {
		IRI lookupGraph = VF.createIRI("urn:path:lookup-graph");
		IRI callerGraph = VF.createIRI("urn:path:caller-graph");
		IRI middle = VF.createIRI("urn:path:middle-context");
		IRI finish = VF.createIRI("urn:path:finish-context");
		Model data = new LinkedHashModel();
		data.add(S, P, middle, lookupGraph);
		data.add(middle, P, finish, lookupGraph);
		Source source = new Source(data);

		ArbitraryLengthPath valuedPath = namedContextPath(Var.of("graph", lookupGraph, false, false));
		BindingSet conflictingCaller = bindings("graph", callerGraph);
		List<Map<String, Value>> firstHopRows = rows(source, valuedPath.getPathExpression().clone(), conflictingCaller);
		List<Map<String, Value>> conflictingRows = rows(source, valuedPath, conflictingCaller);
		List<Map<String, Value>> absentCallerRows = rows(source, valuedPath, EmptyBindingSet.getInstance());

		ArbitraryLengthPath unvaluedPath = namedContextPath(Var.of("graph"));
		List<Map<String, Value>> unvaluedRows = rows(source, unvaluedPath, EmptyBindingSet.getInstance());

		ArbitraryLengthPath fixedPath = namedContextPath(Var.of("graph", lookupGraph, true, true));
		List<Map<String, Value>> fixedRows = rows(source, fixedPath, EmptyBindingSet.getInstance());

		// Establish all ordinary-evaluator rows before checking any output-fact claim.
		assertThat(firstHopRows).containsExactlyInAnyOrder(
				Map.of("pathStart", S, "pathEnd", middle, "graph", callerGraph),
				Map.of("pathStart", middle, "pathEnd", finish, "graph", callerGraph));
		assertThat(conflictingRows).containsExactlyInAnyOrder(
				Map.of("pathStart", S, "pathEnd", middle, "graph", callerGraph),
				Map.of("pathStart", middle, "pathEnd", finish, "graph", callerGraph),
				Map.of("pathStart", S, "pathEnd", finish, "graph", lookupGraph));
		assertThat(absentCallerRows).containsExactlyInAnyOrder(
				Map.of("pathStart", S, "pathEnd", middle, "graph", lookupGraph),
				Map.of("pathStart", middle, "pathEnd", finish, "graph", lookupGraph),
				Map.of("pathStart", S, "pathEnd", finish, "graph", lookupGraph));
		assertThat(unvaluedRows).containsExactlyInAnyOrder(
				Map.of("pathStart", S, "pathEnd", middle, "graph", lookupGraph),
				Map.of("pathStart", middle, "pathEnd", finish, "graph", lookupGraph),
				Map.of("pathStart", S, "pathEnd", finish, "graph", lookupGraph));
		assertThat(fixedRows).hasSize(3).allSatisfy(row ->
				assertThat(row.keySet()).contains("pathStart", "pathEnd"));
		List<List<Value>> fixedEndpointPairs = fixedRows.stream()
				.map(row -> List.of(row.get("pathStart"), row.get("pathEnd"))).toList();
		assertThat(fixedEndpointPairs).containsExactlyInAnyOrder(List.of(S, middle), List.of(middle, finish),
				List.of(S, finish));

		QueryAlgebraBindingAnalysis conflictAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(valuedPath,
				conflictingCaller);
		OutputFacts conflictFacts = conflictAnalysis.outputFacts(valuedPath, conflictAnalysis.contextAt(valuedPath));
		assertOutputFactsAgreeOrDeclineWithObservedRows(conflictFacts, conflictingRows, "graph");

		QueryAlgebraBindingAnalysis absentAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(valuedPath,
				EmptyBindingSet.getInstance());
		assertOutputFactsAgreeOrDeclineWithObservedRows(
				absentAnalysis.outputFacts(valuedPath, absentAnalysis.contextAt(valuedPath)), absentCallerRows, "graph");

		QueryAlgebraBindingAnalysis unvaluedAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(unvaluedPath,
				EmptyBindingSet.getInstance());
		assertOutputFactsAgreeOrDeclineWithObservedRows(
				unvaluedAnalysis.outputFacts(unvaluedPath, unvaluedAnalysis.contextAt(unvaluedPath)), unvaluedRows,
				"graph");

		QueryAlgebraBindingAnalysis fixedAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(fixedPath,
				EmptyBindingSet.getInstance());
		assertOutputFactsAgreeOrDeclineWithObservedRows(
				fixedAnalysis.outputFacts(fixedPath, fixedAnalysis.contextAt(fixedPath)), fixedRows, "graph");
	}

	@Test
	void positiveLengthPathDoesNotFixAChildValueThatChangesWithExpansionContext() {
		IRI lookupGraph = VF.createIRI("urn:path:lookup-graph");
		IRI callerGraph = VF.createIRI("urn:path:caller-graph");
		IRI middle = VF.createIRI("urn:path:middle-context");
		IRI finish = VF.createIRI("urn:path:finish-context");
		Model data = new LinkedHashModel();
		data.add(S, P, middle, lookupGraph);
		data.add(middle, P, finish, lookupGraph);
		Source source = new Source(data);
		Var context = Var.of("graph", lookupGraph, false, false);
		StatementPattern link = new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("pathStart"), constant(P),
				Var.of("pathEnd"), context.clone());
		Extension child = new Extension(link, new ExtensionElem(Var.of("graph"), "marker"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Scope.NAMED_CONTEXTS, Var.of("pathStart"), child,
				Var.of("pathEnd"), context, 1);
		BindingSet input = bindings("graph", callerGraph);

		List<BindingSet> firstHop = bindingSets(source, child.clone(), input);
		assertThat(firstHop).hasSize(2)
				.allSatisfy(row -> assertThat(row.getValue("marker")).isSameAs(callerGraph));
		List<BindingSet> pathRows = bindingSets(source, path, input);
		assertThat(pathRows).hasSize(3);
		assertThat(pathRows).filteredOn(row -> S.equals(row.getValue("pathStart"))
				&& middle.equals(row.getValue("pathEnd"))).singleElement()
				.satisfies(row -> assertThat(row.getValue("marker")).isSameAs(callerGraph));
		assertThat(pathRows).filteredOn(row -> middle.equals(row.getValue("pathStart"))
				&& finish.equals(row.getValue("pathEnd"))).singleElement()
				.satisfies(row -> assertThat(row.getValue("marker")).isSameAs(callerGraph));
		assertThat(pathRows).filteredOn(row -> S.equals(row.getValue("pathStart"))
				&& finish.equals(row.getValue("pathEnd"))).singleElement()
				.satisfies(row -> assertThat(row.getValue("marker")).isSameAs(lookupGraph));

		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(path, input);
		OutputFacts facts = analysis.outputFacts(path, analysis.contextAt(path));
		assertThat(facts.fixedValues()).doesNotContainKey("marker");
	}

	private static ArbitraryLengthPath namedContextPath(Var contextVar) {
		StatementPattern step = new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("pathStart"), constant(P),
				Var.of("pathEnd"), contextVar.clone());
		return new ArbitraryLengthPath(Scope.NAMED_CONTEXTS, Var.of("pathStart"), step, Var.of("pathEnd"), contextVar, 1);
	}

	@Test
	void pathDoesNotClaimAnUnvaluedPreparedEndpointRepresentation() {
		IRI caller = VF.createIRI("urn:", "path:leaf");
		IRI prepared = VF.createIRI("urn:path:", "leaf");
		assertThat(caller.stringValue()).isEqualTo(prepared.stringValue());
		assertThat(caller.getNamespace()).isNotEqualTo(prepared.getNamespace());
		assertThat(caller.getLocalName()).isNotEqualTo(prepared.getLocalName());
		Statement stored = VF.createStatement(prepared, P, O);
		List<Value> lookupSubjects = new ArrayList<>();
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object, Resource... contexts) {
				lookupSubjects.add(subject);
				return new CloseableIteratorIteration<>(List.of(stored).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}

			@Override
			public java.util.function.Function<Value, Value> getValuePreparer() {
				return value -> value == caller ? prepared : value;
			}
		};
		StatementPattern step = new StatementPattern(Var.of("start"), constant(P), Var.of("end"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("start"), step, Var.of("end"), 1);
		BindingSet input = bindings("start", caller);
		List<BindingSet> actual = bindingSets(source, path, input);

		assertThat(lookupSubjects).contains(prepared);
		assertThat(actual).singleElement().satisfies(row -> {
			assertThat(row.getValue("start")).isSameAs(prepared);
			assertThat(row.getValue("end")).isEqualTo(O);
		});
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(path, input);
		OutputFacts facts = analysis.outputFacts(path, analysis.contextAt(path));
		assertThat(facts.fixedValues()).doesNotContainKey("start");
	}

	@Test
	void positiveLengthPathRetainsChildFixedFactsAcrossEndpointExpansion() {
		IRI middle = VF.createIRI("urn:path:middle");
		IRI finish = VF.createIRI("urn:path:finish");
		Model data = new LinkedHashModel();
		data.add(S, P, middle);
		data.add(middle, P, finish);
		StatementPattern link = new StatementPattern(Var.of("pathStart"), constant(P), Var.of("pathEnd"));
		Extension child = new Extension(link,
				new ExtensionElem(new ValueConstant(CALLER_LITERAL), "marker"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("pathStart"), child, Var.of("pathEnd"), 1);
		List<Map<String, Value>> actual = rows(new Source(data), path, EmptyBindingSet.getInstance());
		assertThat(actual).containsExactlyInAnyOrder(
				Map.of("pathStart", S, "pathEnd", middle, "marker", CALLER_LITERAL),
				Map.of("pathStart", middle, "pathEnd", finish, "marker", CALLER_LITERAL),
				Map.of("pathStart", S, "pathEnd", finish, "marker", CALLER_LITERAL));
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(path,
				EmptyBindingSet.getInstance());
		OutputFacts facts = analysis.outputFacts(path, analysis.contextAt(path));
		assertThat(facts.fixedValues().get("marker")).isEqualTo(CALLER_LITERAL);
		assertThat(actual).allSatisfy(row -> assertThat(row.get("marker")).isEqualTo(CALLER_LITERAL));

		MapBindingSet endpoints = new MapBindingSet();
		endpoints.addBinding("pathStart", S);
		endpoints.addBinding("pathEnd", finish);
		assertThat(rows(new Source(data), path, endpoints))
				.containsExactly(Map.of("pathStart", S, "pathEnd", finish, "marker", CALLER_LITERAL));
		QueryAlgebraBindingAnalysis endpointAnalysis = QueryAlgebraBindingAnalysis.withBindingValues(path, endpoints);
		OutputFacts endpointFacts = endpointAnalysis.outputFacts(path, endpointAnalysis.contextAt(path));
		assertThat(endpointFacts.fixedValues()).containsEntry("marker", CALLER_LITERAL);
		assertThat(endpointFacts.fixedValues()).doesNotContainKeys("pathStart", "pathEnd");
	}

