	private static void assertObservedValueIsNotExcluded(OutputFacts facts, String name, Value observedValue) {
		assertThat(facts.canProduceRows()).isTrue();
		Value fixed = facts.fixedValues().get(name);
		if (fixed != null) {
			assertThat(fixed).isEqualTo(observedValue);
		}
		assertObservedKindIsNotExcluded(facts, name, kindOf(observedValue));
	}

	private static void assertObservedKindIsNotExcluded(OutputFacts facts, String name, ValueKind observedKind) {
		Set<ValueKind> kinds = facts.valueKinds().get(name);
		assertThat(kinds == null || kinds.contains(ValueKind.UNKNOWN) || kinds.contains(observedKind))
				.as("facts must include the evaluator's observed kind for %s or decline with UNKNOWN: %s", name, kinds)
				.isTrue();
	}

	private static ValueKind kindOf(Value value) {
		if (value.isIRI()) {
			return ValueKind.IRI;
		} else if (value.isBNode()) {
			return ValueKind.BNODE;
		} else if (value.isLiteral()) {
			return ValueKind.LITERAL;
		} else if (value instanceof TripleTerm) {
			return ValueKind.TRIPLE;
		}
		return ValueKind.UNKNOWN;
	}

	private static EncodedSource encodedSource(BNode reifier, Value subject, Value predicate, Value object) {
		Model data = new LinkedHashModel();
		data.add(reifier, RDF.TYPE, RDF.PROPOSITION_FORM);
		data.add(reifier, RDF.PROPOSITION_FORM_SUBJECT, subject);
		data.add(reifier, RDF.PROPOSITION_FORM_PREDICATE, predicate);
		data.add(reifier, RDF.PROPOSITION_FORM_OBJECT, object);
		return new EncodedSource(data);
	}

