	private static final class OpaqueValueExpr extends AbstractQueryModelNode implements ValueExpr {
		@Override
		public <X extends Exception> void visit(QueryModelVisitor<X> visitor) throws X {
			visitor.meetOther(this);
		}

		@Override
		public <X extends Exception> void visitChildren(QueryModelVisitor<X> visitor) {
			// Opaque leaf: no arguments to traverse.
		}

		@Override
		public void replaceChildNode(QueryModelNode current, QueryModelNode replacement) {
			throw new IllegalArgumentException("Opaque value expression has no children");
		}

		@Override
		public OpaqueValueExpr clone() {
			return (OpaqueValueExpr) super.clone();
		}
	}

	private static void assertOutputFactsAgreeOrDecline(OutputFacts facts, Value expected) {
		assertThat(facts.canProduceRows()).isTrue();
		Value fixed = facts.fixedValues().get("x");
		if (fixed != null) {
			assertThat(fixed).isEqualTo(expected);
		}
		Set<ValueKind> kinds = facts.valueKinds().get("x");
		if (kinds != null && !kinds.contains(ValueKind.UNKNOWN)) {
			assertThat(kinds).contains(valueKind(expected));
		}
	}

	private static void assertOutputFactsAgreeOrDeclineWithObservedRows(OutputFacts facts,
			List<Map<String, Value>> observedRows, String name) {
		assertThat(facts.canProduceRows()).isTrue();
		assertThat(observedRows).isNotEmpty();
		Value fixed = facts.fixedValues().get(name);
		if (fixed != null) {
			assertThat(observedRows).allSatisfy(row -> assertThat(row.get(name)).isEqualTo(fixed));
		}
		Set<ValueKind> kinds = facts.valueKinds().get(name);
		if (kinds != null && !kinds.contains(ValueKind.UNKNOWN)) {
			for (Map<String, Value> row : observedRows) {
				Value value = row.get(name);
				if (value != null) {
					assertThat(kinds).contains(valueKind(value));
				}
			}
		}
	}

	private static ValueKind valueKind(Value value) {
		if (value instanceof IRI) {
			return ValueKind.IRI;
		}
		return ValueKind.LITERAL;
	}

