	private static List<Map<String, Value>> rows(TripleSource source, TupleExpr expression, BindingSet input) {
		return rows(bindingSets(source, expression, input));
	}

	private static List<Map<String, Value>> rows(List<BindingSet> bindingSets) {
		List<Map<String, Value>> rows = new ArrayList<>();
		for (BindingSet bindingSet : bindingSets) {
			Map<String, Value> row = new TreeMap<>();
			for (String name : bindingSet.getBindingNames()) {
				row.put(name, bindingSet.getValue(name));
			}
			rows.add(Map.copyOf(row));
		}
		return rows;
	}

	private static List<BindingSet> bindingSets(TripleSource source, TupleExpr expression, BindingSet input) {
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = new StrictEvaluationStrategy(source, null)
				.precompile(expression).evaluate(input)) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private static List<BindingSet> bindingSets(TripleSource source, TupleExpr expression, BindingSet input,
			FederatedService service) {
		FederatedServiceResolver resolver = ignored -> service;
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = new StrictEvaluationStrategy(source, resolver)
				.precompile(expression).evaluate(input)) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private static void assertFailedDependentExtensionDoesNotGuaranteeLeftInput(TupleExpr candidate) {
		Source source = new Source(new LinkedHashModel());
		List<Map<String, Value>> ordinaryOperatorRows = rows(source, candidate, EmptyBindingSet.getInstance());
		assertThat(ordinaryOperatorRows).as("raw ordinary operator rows: %s", candidate).containsExactly(Map.of());

		Filter bound = new Filter(candidate.clone(), new Bound(Var.of("x")));
		List<Map<String, Value>> ordinaryBoundRows = rows(source, bound, EmptyBindingSet.getInstance());
		assertThat(ordinaryBoundRows).as("ordinary BOUND(?x) bag: %s", bound).isEmpty();

		TupleExpr optimized = new QueryRoot(bound.clone());
		new DefaultEvaluationStrategy(source, url -> null).optimize(optimized, new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(candidate,
				EmptyBindingSet.getInstance());
		var facts = analysis.outputFacts(candidate, analysis.contextAt(candidate));
		org.junit.jupiter.api.Assertions.assertAll(
				() -> assertThat(rows(source, optimized, EmptyBindingSet.getInstance()))
						.as("optimized BOUND(?x) bag must match the ordinary empty bag\n%s", optimized).isEmpty(),
				() -> assertThat(facts.guaranteedOutputs())
						.as("a failed dependent RHS write can remove the left x binding: %s", candidate)
						.doesNotContain("x"),
				() -> assertThat(facts.fixedValues()).as("a maybe-failed RHS write cannot fix x: %s", candidate)
						.doesNotContainKey("x"),
				() -> assertThat(facts.valueKinds()).as("a maybe-failed RHS write cannot narrow x: %s", candidate)
						.doesNotContainKey("x"),
				() -> {
					if (candidate instanceof Join join) {
						TupleExprs.ConditionBindingDomain observations = TupleExprs
								.tupleBindingObservationDomain(join.getRightArg());
						org.junit.jupiter.api.Assertions.assertAll(
								() -> assertThat(observations.known())
										.as("the Extension observation domain must be proved")
										.isTrue(),
								() -> assertThat(observations.names())
										.as("Extension expression references are reorder observations")
										.contains("x"),
								() -> assertSingleJoinOrder(optimized, BindingSetAssignment.class, Extension.class));
					}
				});
	}

	private static void assertSingleJoinOrder(TupleExpr expression, Class<?> leftType, Class<?> rightType) {
		List<Join> joins = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Join join) {
				joins.add(join);
				super.meet(join);
			}
		});
		assertThat(joins).singleElement().satisfies(join -> {
			assertThat(join.getLeftArg()).isInstanceOf(leftType);
			assertThat(join.getRightArg()).isInstanceOf(rightType);
		});
	}

