		Object identityScope = new Object();
		RemoteBNode.ResponseScope response = RemoteBNode.newResponseScope(new BlankNodeAllocationScope(), VF,
				identityScope, true);
		BNode remote = (BNode) response.map(VF.createBNode("canonical-remote-id"));
