	private static void assertServiceAuthorityParity(Value first, Value second, Object identityScope,
			boolean secondTrusted) {
		Source source = new Source(new LinkedHashModel());
		TupleExpr candidate = serviceValuesCandidate(first, second);
		IdentityAwareService ordinaryService = new IdentityAwareService(identityScope);
		List<BindingSet> ordinaryBindings = bindingSets(source, candidate, EmptyBindingSet.getInstance(), ordinaryService);
		assertThat(ordinaryBindings).hasSize(2);
		assertThat(ordinaryBindings.get(0).hasBinding("serviceResult")).isTrue();
		assertThat(ordinaryBindings.get(1).hasBinding("serviceResult")).isEqualTo(secondTrusted);
		assertThat(ordinaryService.selectCalls).isEqualTo(secondTrusted ? 2 : 1);

		List<Map<String, Value>> expected = new ArrayList<>();
		expected.add(Map.of("source", first, "forwarded", first, "serviceResult", SERVICE_RESULT));
		expected.add(secondTrusted
				? Map.of("source", second, "forwarded", second, "serviceResult", SERVICE_RESULT)
				: Map.of("source", second, "forwarded", second));
		assertThat(rows(ordinaryBindings)).as("ordinary SERVICE bag").containsExactlyElementsOf(expected);

		IdentityAwareService optimizedService = new IdentityAwareService(identityScope);
		TupleExpr optimized = new QueryRoot(candidate.clone());
		FederatedServiceResolver resolver = ignored -> optimizedService;
		new DefaultEvaluationStrategy(source, resolver).optimize(optimized, new EvaluationStatistics(),
				EmptyBindingSet.getInstance());
		List<BindingSet> optimizedBindings = bindingSets(source, optimized, EmptyBindingSet.getInstance(),
				optimizedService);
		BindingSetAssignment assignment = values("source", first, second);
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(assignment,
				EmptyBindingSet.getInstance());
		OutputFacts facts = analysis.outputFacts(assignment, analysis.contextAt(assignment));
		List<Map<String, Value>> optimizedRows = rows(optimizedBindings);
		org.junit.jupiter.api.Assertions.assertAll(
				() -> assertThat(optimizedRows)
						.as("optimized SERVICE bag must preserve blank-node authority\n%s", optimized)
						.containsExactlyElementsOf(expected),
				() -> {
					if (secondTrusted) {
						assertThat(facts.fixedValues().get("source")).isSameAs(first);
					} else {
						assertThat(facts.fixedValues()).doesNotContainKey("source");
					}
				});
	}

	private static TupleExpr serviceValuesCandidate(Value first, Value second) {
		Extension alias = new Extension(values("source", first, second),
				new ExtensionElem(Var.of("source"), "forwarded"));
		StatementPattern serviceBody = new StatementPattern(Var.of("forwarded"), constant(P), Var.of("serviceResult"));
		Service service = new Service(Var.of("endpoint", SERVICE_ENDPOINT, true, true), serviceBody,
				"?forwarded <urn:fixed:p> ?serviceResult", Map.of(), null, true);
		return new Join(alias, service);
	}

